arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *[Uu]sername*) printf '%s\n' "x-access-token" ;;
  *[Pp]assword*) printf '%s\n' "$GITHUB_TOKEN" ;;
  *) printf '%s\n' "" ;;
esac
EOF
chmod 700 /tmp/askpass.sh && cd /tmp/friend-rachel && GIT_ASKPASS=/tmp/askpass.sh git push origin friend/rachel 2>&1 | sed -E 's#//[^@]*@#//REDACTED@#g' | tail -8
